import { fmt, n, q, num, L, U } from "./ee-shape.mjs";

const d24 = 5 / 24;
const d18 = 5 / 18;
const fSw = 100e3;
const lBuck = 220e-6;
const di24 = ((24 - 5) * d24) / (fSw * lBuck);
const di18 = ((18 - 5) * d18) / (fSw * lBuck);
const iPeak = 1 + di24 / 2;
const iBound = di24 / 2;
const esrMax = 0.1 / di24;
const dvCap = di24 / (8 * fSw * 100e-6);
const pSwitch = 0.1 * d24;
const pDiode = 0.5 * (1 - d24);
const pDcr = 0.1;
const pLoss = pSwitch + pDiode + pDcr;
const eta = 5 / (5 + pLoss);
const dBoost = 1 - 12 / 24;
const diBoost = (12 * dBoost) / (fSw * 100e-6);
const iInBoost = 1 / (1 - dBoost);
const dBb = 5 / (5 + 12);
const iInBb = 0.5 * (5 / 12);
const dFly = 5 / 11;
const lFly = 220e-6;
const iInFly = 5 / 24;
const iOn = iInFly / dFly;
const diFly = (24 * dFly) / (fSw * lFly);
const iPkFly = iOn + diFly / 2;

